<?php
declare(strict_types=1);
if(session_status()!==PHP_SESSION_ACTIVE)session_start();
require_once __DIR__.'/../lib/admin-users.php';
ferrn_require_admin_permission('users');
$user=ferrn_current_admin();if(($user['role']??'')!=='super'){http_response_code(403);exit('Super administrator only.');}
if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));
$csrf=(string)$_SESSION['csrf'];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Invalid request.');}
 $action=(string)($_POST['action']??'');$users=ferrn_admin_users();$id=(string)($_POST['id']??'');
 if($action==='create'){
  $email=strtolower(trim((string)($_POST['email']??'')));$name=trim((string)($_POST['name']??''));
  if(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($name)<2)$error='Enter a valid email and name.';
  elseif($email==='michael@ferrnagency.com'||count(array_filter($users,fn($u)=>strtolower((string)($u['email']??''))===$email)))$error='This email is already registered.';
  else{
    $pw=ferrn_random_temp_password();
    $users[]=['id'=>bin2hex(random_bytes(12)),'name'=>mb_substr($name,0,160),'email'=>$email,'password_hash'=>password_hash($pw,PASSWORD_DEFAULT),'role'=>'admin','permissions'=>ferrn_sanitize_permissions((array)($_POST['permissions']??[])),'active'=>true,'must_change'=>true,'created_at'=>date(DATE_ATOM)];
    if(ferrn_save_admin_users($users)){$_SESSION['new_admin_credential']=['email'=>$email,'password'=>$pw];header('Location:/admin/users.php');exit;}else $error='Could not create user.';
  }
 }
 if(in_array($action,['update','toggle','reset'],true)){
  foreach($users as &$u){
   if(($u['id']??'')!==$id)continue;
   if($action==='update'){$u['permissions']=ferrn_sanitize_permissions((array)($_POST['permissions']??[]));$u['active']=!empty($_POST['active']);}
   elseif($action==='toggle')$u['active']=empty($u['active']);
   elseif($action==='reset'){$pw=ferrn_random_temp_password();$u['password_hash']=password_hash($pw,PASSWORD_DEFAULT);$u['must_change']=true;$_SESSION['new_admin_credential']=['email'=>$u['email'],'password'=>$pw];}
   $u['updated_at']=date(DATE_ATOM);break;
  }unset($u);
  if(ferrn_save_admin_users($users)){header('Location:/admin/users.php');exit;}
  $error='Could not update user.';
 }
}
$users=ferrn_admin_users();$cred=$_SESSION['new_admin_credential']??null;unset($_SESSION['new_admin_credential']);
?><!doctype html><html lang="en" data-admin-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin users — Ferrn</title><link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/admin-unified.css"><script src="/assets/admin-unified.js" defer></script><style>.users-grid{display:grid;grid-template-columns:380px minmax(0,1fr);gap:16px;align-items:start}.permissions{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:7px;margin:16px 0}.permissions label{border:1px solid var(--adm-border);border-radius:9px;padding:9px;font-size:10.5px}.account-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.account-top h3{margin:0}.account-meta{font-size:10px;color:var(--adm-muted);margin-top:5px}.secret{padding:16px;margin:14px 0}.secret code{font-size:15px;word-break:break-all}@media(max-width:1050px){.users-grid{grid-template-columns:1fr}}</style></head><body><div class="app"><?php $tab='users';include __DIR__.'/sidebar.php'; ?><main class="main"><div class="top"><div><div class="muted">ACCESS CONTROL</div><h1>Admin users</h1></div></div><p class="muted">Control who can access the Ferrn admin and exactly which sections each teammate can manage.</p><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><?php if($cred):?><section class="secret" role="status"><strong>Temporary login credentials</strong><p>Email: <?=htmlspecialchars($cred['email'])?></p><p>Password: <code><?=htmlspecialchars($cred['password'])?></code></p><p class="muted">Copy this now. It will not be shown again, and the user must change it at first sign-in.</p></section><?php endif;?><div class="users-grid"><section class="panel"><h2>Create a user</h2><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="action" value="create"><div class="field"><label>Full name</label><input name="name" required></div><div class="field" style="margin-top:12px"><label>Work email</label><input type="email" name="email" required></div><h3>Editable sections</h3><div class="permissions"><?php foreach(ferrn_permission_keys() as $key=>$label):?><label><input type="checkbox" name="permissions[<?=htmlspecialchars($key)?>]" value="1" <?=$key==='dashboard'?'checked':''?>> <?=htmlspecialchars($label)?></label><?php endforeach;?></div><button class="btn">Create admin account</button></form></section><section class="panel"><div class="panel-head"><h2>Existing users</h2><span class="muted"><?=count($users)?> users</span></div><?php if(!$users):?><p class="muted">No additional admins yet.</p><?php endif;?><?php foreach($users as $u):$active=!empty($u['active']);?><article class="account <?=$active?'':'is-disabled-row'?>"><div class="account-top"><div><h3><?=htmlspecialchars($u['name'])?></h3><div class="account-meta"><?=htmlspecialchars($u['email'])?> · <?=!empty($u['must_change'])?'Password change required':'Password set'?></div></div><span class="status-pill <?=$active?'is-active':'is-disabled'?>"><?=$active?'Enabled':'Disabled'?></span></div><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="id" value="<?=htmlspecialchars($u['id'])?>"><input type="hidden" name="action" value="update"><div class="permissions"><?php foreach(ferrn_permission_keys() as $key=>$label):?><label><input type="checkbox" name="permissions[<?=htmlspecialchars($key)?>]" value="1" <?=!empty($u['permissions'][$key])?'checked':''?>> <?=htmlspecialchars($label)?></label><?php endforeach;?></div><label class="check"><input type="checkbox" name="active" value="1" <?=$active?'checked':''?>> Account enabled</label><div class="actions" style="margin-top:14px"><button class="btn">Save permissions</button></div></form><div class="actions" style="margin-top:10px"><form method="post" onsubmit="return confirm('Issue a new temporary password?')"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="id" value="<?=htmlspecialchars($u['id'])?>"><input type="hidden" name="action" value="reset"><button class="btn secondary">Reset password</button></form><form method="post" onsubmit="return confirm('<?= $active?'Disable':'Enable' ?> this account?')"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="id" value="<?=htmlspecialchars($u['id'])?>"><input type="hidden" name="action" value="toggle"><button class="btn <?=$active?'danger':'secondary'?>"><?=$active?'Disable account':'Enable account'?></button></form></div></article><?php endforeach;?></section></div></main></div></body></html>